alter default privileges in schema private revoke all on tables from public,anon,authenticated;
alter default privileges in schema private revoke all on sequences from public,anon,authenticated;
alter default privileges in schema private revoke all on functions from public,anon,authenticated;
alter default privileges in schema private grant all on tables to service_role;
alter default privileges in schema private grant usage,select on sequences to service_role;
alter default privileges in schema private grant execute on functions to service_role;
comment on schema private is 'Server-only identity, authorization and configuration data; not exposed through the Data API.';
comment on table public.profiles is 'Shared public profile source for Expo Web, Android, iOS, Admin and Public Web; contains no email, DOB, KYC, bank or exact location.';
comment on table private.user_identity is 'Server-only date of birth, age assurance and policy acceptance.';
comment on table private.user_roles is 'Authoritative roles; never derive authorization from raw_user_meta_data.';
comment on table private.app_config is 'Server-owned configuration; clients read public keys only through get_public_app_config().';
